"""
    Computer Intersection Over Union
    """
def get_iou(box1: list[int], box2: list[int]) -> float {
    xA = max(box1[0], box2[0]);
    yA = max(box1[1], box2[1]);
    xB = min(box1[2], box2[2]);
    yB = min(box1[3], box2[3]);
    inter_area = max(0, xB - xA + 1) * max(0, yB - yA + 1);
    box1_area = (box1[2] - box1[0] + 1) * (box1[3] - box1[1] + 1);
    box2_area = (box2[2] - box2[0] + 1) * (box2[3] - box2[1] + 1);
    union_area = box1_area + box2_area - inter_area;
    return inter_area / float(union_area);
}

""" Guess an appropriate chunk layout for a dataset, given its shape and
    the size of each element in bytes.  Will allocate chunks only as large
    as MAX_SIZE.  Chunks are generally close to some power-of-2 fraction of
    each axis, slightly favoring bigger values for the last index.

    Undocumented and subject to change without warning.
    """
def guessChunk(shape_json: dict[str, str | list[int]] | None, typesize: int | str) -> tuple[int, ...] | None {
    if shape_json is None or shape_json["class"] == 'H5S_NULL' {
        return None;
    }
    if shape_json["class"] == 'H5S_SCALAR' {
        return (1,);
    }
    if "maxdims" in shape_json {
        shape = shape_json["maxdims"];
    } else {
        shape = shape_json["dims"];
    }
    if typesize == 'H5T_VARIABLE' {
        typesize = 128;
    }
    shape = tuple(x if x != 0 else 1024 for (i, x) in enumerate(shape));
    return shape;
}

"""Calculate the Julian Day from a (year, month, day, hour, minute, second, microsecond) tuple"""
def _julian_day(dt: tuple[int, int, int, int, int, int, int]) -> float {
    (yr, mo, dy, hr, mn, sc, us) = dt;
    if mo <= 2 {
        mo += 12;
        yr -= 1;
    }
    dy = dy
        + hr / 24.0
        + mn / (24.0 * 60.0)
        + sc / (24.0 * 60.0 * 60.0)
        + us / (24.0 * 60.0 * 60.0 * 1000000.0);
    a = int(yr / 100);
    b = 2 - a + int(a / 4);
    jd = int(365.25 * (yr + 4716)) + int(30.6001 * (mo + 1)) + dy + b - 1524.5;
    return jd;
}

