"""
Compute x0_mult element-wise
Arguments:
    guess (np.array)
    slip (np.array)
"""
def x0_mult(guess: list[float], slip: list[float]) -> list[float] {
    return (slip * (1.0 + guess)) / (1.0 + slip);
}

"""Calculate water vapor mixing ratio (1) from specific humidity q (1)."""
def calc_w_from_q(q: float) -> float {
    return q / (1.0 - q);
}

