"""
Return the column-stacked-matrix-basis labels based on a matrix dimension.
"""
def col_labels(matrix_dim: int) -> list[str] {
    if matrix_dim == 0 {
        return [];
    }
    if matrix_dim == 1 {
        return [''];
    }
    return [("(%d,%d)" % (j, i)) for i in range(matrix_dim) for j in range(matrix_dim)];
}

"""Return list of (start, end , [list of subtokens]) for each token."""
def partition_subtokens(subtokens: list[str]) -> list[tuple[int, int, list[str]]] {
    words = [];
    last = 0;
    for (i, token) in enumerate(subtokens) {
        if token[-1] == '_' {
            words.append((last, i + 1, subtokens[last:(i + 1)]));
            last = i + 1;
        }
    }
    return words;
}

