"""
Formula:
Number of times term w appears in a document) / (Total number of terms in the document).
"""
def tf_score(word: str, sentence: str) -> float {
    word_frequency = 0;
    len_sentence = len(sentence);
    for token in sentence.split() {
        if word == token {
            word_frequency += 1;
        }
    }
    return word_frequency / len_sentence;
}

"""
This function splits a full name into a natural first name, last name
and middle initials.
"""
def full_name_natural_split(full_name: str) -> tuple[str, str, str] {
    parts = full_name.strip().split(' ');
    first_name = "";
    if parts {
        first_name = parts.pop(0);
    }
    if first_name.lower() == "el" and parts {
        first_name += " " + parts.pop(0);
    }
    last_name = "";
    if parts {
        last_name = parts.pop();
    }
    if last_name.lower() in ('i', 'ii') or last_name.lower() == 'iii' and parts {
        last_name = parts.pop() + " " + last_name;
    }
    middle_initials = "";
    for middle_name in parts {
        if middle_name {
            middle_initials += middle_name[0];
        }
    }
    return (first_name, middle_initials, last_name);
}

"""Normalizes the difference between actual and predicted values."""
def magnitude_relative_error(
    estimate: float, actual: float, balanced: bool = False
) -> float {
    if not balanced {
        denominator = actual;
    } else {
        denominator = min(estimate, actual);
    }
    if denominator == 0 {
        denominator = 1;
    }
    return float(abs(estimate - actual)) / float(denominator);
}

