"""Set which attributes should have values inferred from ancestral taxa."""
def set_attributes_to_descend(
    meta: dict[str, dict[str, str | bool | int]],
    traverse_limit: int
) -> tuple[set[str], dict[str, int]] {
    desc_attrs = set();
    desc_attr_limits = {};
    for (key, value) in meta.items() {
        if "traverse" in value and value["traverse"] {
            if (
                "traverse_direction" not in value
                or value["traverse_direction"] in ("down", "both")
            ) {
                desc_attrs.add(key);
                if "traverse_limit" in value {
                    desc_attr_limits.update({key: value["traverse_limit"]});
                } else {
                    desc_attr_limits.update({key: traverse_limit});
                }
            }
        }
    }
    return (desc_attrs, desc_attr_limits);
}

"""
    Estimation of time to go from position_0 to position_1
    FIXME : Does not take into account forbidden angle, and
            rotation direction neither (shortest path is chosen)
            works with
    """
def pt_time_estimation(
    position_0: tuple[float, float] | None,
    position_1: tuple[float, float] | None,
    pan_speed: float = 22.5,
    tilt_speed: float = 6.5,
    unit: float = 0.01
) -> float | None {
    if position_0 is None or position_1 is None {
        return;
    }
    (pan0, tilt0) = position_0;
    (pan1, tilt1) = position_1;
    return unit * max(abs(pan1 - pan0) / pan_speed, abs(tilt1 - tilt0) / tilt_speed);
}

