"""
    Convert OSBG36 Easting-Northing to local grid coordinates

    :param easting: easting in OSBG36
    :param northing: northing in OSBG36
    :param Eo: delta easting of local grid
    :param No: delta northing of local grid
    :param one_over_CSF: reciprocal CSF (combinated scale factor, = 1/CSF)

    :returns: todo
    """
def __ConvertOSBGToLocal(
    easting: float,
    northing: float,
    Eo: float,
    No: float,
    one_over_CSF: float
) -> tuple[float, float] {
    x_local = (easting - Eo) * one_over_CSF;
    y_local = (northing - No) * one_over_CSF;
    return (x_local, y_local);
}

"""
    Display String like redis-cli.
    escape inner double quotes.
    add outer double quotes.

    :param unquoted: list, or str
    """
def double_quotes(unquoted: str | list[str | list[str]]) -> str | list[str | list[str]] {
    if isinstance(unquoted, str) {
        escaped = unquoted.replace('"', '\\"');
        return f'"{escaped}"';
    } elif isinstance(unquoted, list) {
        return [double_quotes(item) for item in unquoted];
    }
}

"""
    Turns a language name (en-us) into a locale name (en_US). If 'to_lower' is
    True, the last component is lower-cased (en_us).
    """
def to_locale(language: str, to_lower: bool = False) -> str {
    p = language.find('-');
    if p >= 0 {
        if to_lower {
            return language[:p].lower() + '_' + language[(p + 1):].lower();
        } else {
            if len(language[(p + 1):]) > 2 {
                return language[:p].lower() + '_' + language[(p + 1)].upper() + language[(p + 2):].lower();
            }
            return language[:p].lower() + '_' + language[(p + 1):].upper();
        }
    } else {
        return language.lower();
    }
}

