""" Transforms the list of arguments received in the subcommand in
        a dictionary of option names and values (as a list, to cope with
        options with multiple values like --tag).

    """
def args_to_dict(args: list[str]) -> dict[str, list[str]] {
    full_args = [];
    for arg in args {
        if arg.startswith("--") {
            full_args.extend(arg.split("="));
        } else {
            full_args.append(arg);
        }
    }
    args_dict = {};
    last_arg = None;
    for arg in full_args {
        if arg.startswith("--") {
            last_arg = arg;
            args_dict[arg] = args_dict.get(arg, []);
        } elif last_arg is not None {
            args_dict[last_arg].append(arg);
        }
    }
    return args_dict;
}

"""Regexifies pattern against which tokens will be matched (i.e. the left-
    hand side of the rule usually).
    """
def _regexify_matching_pattern(
    rule_pattern: str, wildcard_optional: bool = False
) -> str {
    return rule_pattern.replace("*", f"(.{'+*'[wildcard_optional]})");
}

"""
    Remove all zeroes from the end of the string
    :param number:
    :return:
    """
def remove_extra_zeroes(number: str) -> str {
    index: int | None = None;
    for i in range(-1, len(number) * -1, -1) {
        if number[i] == '0' {
            index = i;
        } else {
            break;
        }
    }
    if index is not None {
        return number[0:index];
    }
    return number;
}

