""" merge sort works by recursively spliting a list down to a
    binary comparison and then sorting smaller values to the left
    """
def mergesort(_list: list[int]) -> list[int] {
    if not isinstance(_list, list) {
        raise TypeError;
    }
    if len(_list) > 1 {
        half = len(_list) // 2;
        left_half = _list[:half];
        right_half = _list[half:];
        mergesort(left_half);
        mergesort(right_half);
        i = 0;
        j = 0;
        k = 0;
        while i < len(left_half) and j < len(right_half) {
            if left_half[i] < right_half[j] {
                _list[k] = left_half[i];
                i += 1;
            } else {
                _list[k] = right_half[j];
                j += 1;
            }
            k += 1;
        }
        while i < len(left_half) {
            _list[k] = left_half[i];
            i += 1;
            k += 1;
        }
        while j < len(right_half) {
            _list[k] = right_half[j];
            j += 1;
            k += 1;
        }
    }
    return _list;
}

"""Return True if a given word or phrase is an isogram."""
def is_isogram(string: str) -> bool {
    letters = [
        letter
        for letter in string.casefold()
        if letter.isalpha()
    ];
    return len(letters) == len(set(letters));
}

"""Elide text so it uses a maximum of length chars."""
def elide(text: str, length: int) -> str {
    if length < 1 {
        raise ValueError("length must be >= 1!");
    }
    if len(text) <= length {
        return text;
    }
    return text[:(length - 1)] + '\u2026';
}

"""
    returns the high or medium degree node with a given label index
    labels contains the output of the label function:
    the sorted list of high degree nodes with their labels, and
    the sorted list of medium degree nodes with their labels
    note that label indices are 0-indexed too
    """
def label_index2node(
    label_index: int,
    labels: tuple[list[tuple[int, int]], list[tuple[int, int]]]
) -> int {
    (hi_pairs, med_pairs) = labels;
    if label_index < len(hi_pairs) {
        return hi_pairs[label_index][0];
    }
    error_msg = "there is no node with label " + str(label_index);
    assert label_index - len(hi_pairs) < len(med_pairs), error_msg;
    return med_pairs[label_index - len(hi_pairs)][0];
}

"""
    Converts a list of cpu cores in corresponding hex value
    of cpu-mask
    """
def comma_list_to_hex(cpus: str) -> str {
    binary_mask = 0;
    for cpu in cpus.split(",") {
