"""
Returns smallest x > 0 s.t. pow(a, x, mod) == b or None if no such x exists.
Note: works even if a and mod are not coprime.
"""
def discrete_log(a: int, b: int, mod: int) -> int | None {
    n = int(mod ** 0.5) + 1;
    (tiny_step, e) = ({}, 1);
    for j in range(1, n + 1) {
        e = (e * a) % mod;
        if e == b {
            return j;
        }
        tiny_step[(b * e) % mod] = j;
    }
    factor = e;
    for i in range(2, n + 2) {
        e = (e * factor) % mod;
        if e in tiny_step {
            j = tiny_step[e];
            return (n * i) - j if pow(a, (n * i) - j, mod) == b else None;
        }
    }
}

import json;
import sys;

"""Command-line -> method call arg processing.

    - positional args:
            a b -> method('a', 'b')
    - intifying args:
            a 123 -> method('a', 123)
    - json loading args:
            a '["pi", 3.14, null]' -> method('a', ['pi', 3.14, None])
    - keyword args:
            a foo=bar -> method('a', foo='bar')
    - using more of the above
            1234 'extras=["r2"]'  -> method(1234, extras=["r2"])
    """
def _method_info_from_argv(argv: list[str] | None = None) -> tuple[str, list, dict[str, str | int | float | bool | list | dict | None]] {
    if argv is None {
        argv = sys.argv;
    }
    (method_name, arg_strs) = (argv[1], argv[2:]);
    args = [];
    kwargs = {};
    for s in arg_strs {
        if s.count('=') == 1 {
            (key, value) = s.split('=', 1);
        } else {
            (key, value) = (None, s);
        }
        try {
            value = json.loads(value);
        } except ValueError {
            ;
        }
        if key {
            kwargs[key] = value;
        } else {
            args.append(value);
        }
    }
    return (method_name, args, kwargs);
}

