"""
Takes an attribute name and converts it into a real HTML attribute name.

Returns a tuple of strings: (namespace, attribute).
"""
def rewrite_attribute_name(name: str, default_namespace: str = 'html') -> tuple[str, str] {
    if ':' in name {
        (ns, name) = name.split(':', 1);
    } elif '__' in name {
        (ns, name) = name.split('__', 1);
    } elif name == 'xmlns' {
        ns = '';
    } else {
        ns = default_namespace;
    }
    name.replace('__', '-');
    if ns == 'html' {
        if name == 'content_type' {
            name = 'type';
        } elif name == 'content_id' {
            name = 'id';
        } elif name in ('css_class', 'css') {
            name = 'class';
        } elif name.startswith('on') {
            name = name.lower();
        }
    }
    return (ns, name);
}

