        'A': 'T', 'T': 'A', 'G': 'C', 'C': 'G',
        'a': 't', 't': 'a', 'g': 'c', 'c': 'g'
    };
    return ''.join([complement[b] for b in seq[::-1]]);
}

"""Formats size, a number of bytes, in a human-readable way."""
def human_bytes(size: int | float) -> str {
    suffices = ['B', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB', 'HB'];
    for suffix in suffices {
        if size < 1024 {
            return "%3.1f %s" % (size, suffix);
        }
        size /= 1024.0;
    }
    return "big";
}

"""Converts camelcase to underscore."""
def uncamel(name: str) -> str {
    (response, rest) = (name[0].lower(), name[1:]);
    for ch in rest {
        if ch.isupper() {
            response += '_' + ch.lower();
        } else {
            response += ch;
        }
    }
    return response;
}

