"""

    :param direction:
    :param position:
    :param boat_size:
    :param board_matrix:
    :return:
    """
def hits_boat(
    direction: str,
    position: dict[str, int],
    boat_size: int,
    board_matrix: list[list[int]]
) -> bool {
    match direction {
        case 'UP':
            first_square = position['y'];
            for current_y in range(first_square + 1 - boat_size, first_square + 1) {
                if board_matrix[current_y][position['x']] != 0 {
                    return True;
                }
            }
        case 'DOWN':
            first_square = position['y'];
            for current_y in range(first_square, first_square + boat_size) {
                if board_matrix[current_y][position['x']] != 0 {
                    return True;
                }
            }
        case 'RIGHT':
            first_square = position['x'];
            for current_x in range(first_square, first_square + boat_size) {
                if board_matrix[position['y']][current_x] != 0 {
                    return True;
                }
            }
        case 'LEFT':
            first_square = position['x'];
            for current_x in range(first_square + 1 - boat_size, first_square + 1) {
                if board_matrix[position['y']][current_x] != 0 {
                    return True;
                }
            }
        case _:
            pass;
    }
    return False;
}

