        raise TypeError("param 'string' must be a string");
    }
    if not isinstance(target, str) {
        raise TypeError("param 'target' must be a string");
    }
    return string[len(target) * -1:] == target;
}

"""
    Consolidate compositional elemental arrays with no repeating elements.
    """
def _consolidate_elemental_array_(elemental_array: list[dict[str, int | str]]) -> list[dict[str, int | str]] {
    condensed_array: list[dict[str, int | str]] = [];
    for e in elemental_array {
        exists = False;
        for k in condensed_array {
            if k["symbol"] == e["symbol"] {
                exists = True;
                k["occurances"] += e["occurances"];
                break;
            }
        }
        if not exists {
            condensed_array.append(e);
        }
    }
    return condensed_array;
}

"""Returns min element (or None if there are no elements)."""
def min_(xs: list[int]) -> int | None {
