the *hotkey* attribute, or ``None`` if no character matches.
"""
def find_hotkey(text: str, attrs: list[tuple[str, int]], hotkey: str = 'hotkey') -> str | None {
    ix = 0;
    for (attr, rl) in attrs {
        if attr == hotkey {
            return text[ix];
        }
        ix += rl;
    }
    return None;
}

