glob SECONDS_PER_DAY = 86400;
glob SECONDS_PER_HOUR = 3600;
glob SECONDS_PER_MINUTE = 60;

"""Print a number of seconds in a terse, human-readable format.

    Adapted from: https://gist.github.com/thatalextaylor/7408395
    """
def pretty_time_delta(seconds: int | float) -> str {
    seconds = int(seconds);
    (days, seconds) = divmod(seconds, SECONDS_PER_DAY);
    (hours, seconds) = divmod(seconds, SECONDS_PER_HOUR);
    (minutes, seconds) = divmod(seconds, SECONDS_PER_MINUTE);
    if days > 0 {
        return '%dd%dh%dm%ds' % (days, hours, minutes, seconds);
    }
    if hours > 0 {
        return '%dh%dm%ds' % (hours, minutes, seconds);
    }
    if minutes > 0 {
        return '%dm%ds' % (minutes, seconds);
    }
    return '%ds' % (seconds,);
}

