"""Converts the pixel to grayscale using the given weights (or 1 by default) casting to int."""
def gray(px: list[int | float], *weights: int | float, cast: type = int) -> float {
    y = cast(0);
    w = cast(0);
    for x in range(len(px)) {
        z = cast(px[x]);
        try {
            y += z * weights[x];
            w += weights[x];
        } except Exception {
            y += z;
            w += 1;
        }
    }
    return y / w;
}

