"""Implements a comparator using the lexicographical ordering of octets as unsigned integers."""
def _bytearray_comparator(a: bytearray, b: bytearray) -> int {
    a_len = len(a);
    b_len = len(b);
    i = 0;
    while i < a_len and i < b_len {
        a_byte = a[i];
        b_byte = b[i];
        if a_byte != b_byte {
            return -1 if a_byte < b_byte else 1;
        }
        i += 1;
    }
    len_diff = a_len - b_len;
    if len_diff < 0 {
        return -1;
    }
    if len_diff > 0 {
        return 1;
    }
    return 0;
}

"""Convert unit from [len_unit] => [len_unit1]."""
def convert_LengthUnit(len_unit1: str, len_unit: str) -> tuple[str, int | float] {
    if len_unit1 == "" or len_unit1 == len_unit {
        return (len_unit, 1);
    }
    conversions = {
        "ft_km": 0.0003048,
        "kt_km": 1.852,
        "mi_km": 1.609344,
        "m_km": 0.001,
        "km_ft": 3280.8399,
        "km_kt": 0.53996,
        "km_mi": 0.621371,
        "km_m": 1000,
        "km_km": 1
    };
    via_km = conversions[len_unit + "_km"];
    to_target = conversions["km_" + len_unit1];
    return (len_unit1, via_km * to_target);
}

