"""
    >>> upper_bound([1, 2, 2, 3, 4], 2)
    3
    >>> upper_bound([1, 2, 2, 3, 4], 5)
    -1
    """
def upper_bound(l: list[int], k: int) -> int {
    if l[-1] <= k {
        return -1;
    }
    i = len(l) // 2;
    (start, end) = (0, len(l) - 1);
    while start < end {
        if l[i] > k {
            end = i;
        } else {
            start = i + 1;
        }
        i = start + (end - start) // 2;
    }
    return i;
}

"""
  Parses an S-Expression into a list-based tree.

  parse_sexp("(+ 5 (+ 3 5))") results in [['+', '5', ['+', '3', '5']]]
  """
def parse_sexp(string: str) -> list[str | list] {
    sexp = [[]];
    word = '';
    in_str = False;
    for c in string {
        if c == '(' and not in_str {
            sexp.append([]);
        } elif c == ')' and not in_str {
            if word {
                sexp[-1].append(word);
                word = '';
            }
            temp = sexp.pop();
            sexp[-1].append(temp);
        } elif c in (' ', '\n', '\t') and not in_str {
            if word != '' {
                sexp[-1].append(word);
                word = '';
            }
        } elif c == '\"' {
            in_str = not in_str;
        } else {
            word += c;
        }
    }
    return sexp[0];
}

