glob HFLIP_MASK = 1 << 31;
glob VFLIP_MASK = 1 << 30;
glob DFLIP_MASK = 1 << 29;

"""
Parse the GID given and return a tuple with the following values:

- The real GID without bitwise flags.
- Whether or not the tile is horizontally flipped.
- Whether or not the tile is vertically flipped.
- Whether or not the tile is "diagonally" flipped.

This is a low-level function used internally by this library; you
don't typically need to use it.
"""
def t_gid_parse(gid: int) -> tuple[int, bool, bool, bool] {
    rgid = gid - (gid & HFLIP_MASK) - (gid & VFLIP_MASK) - (gid & DFLIP_MASK);
    hflip = bool(gid & HFLIP_MASK);
    vflip = bool(gid & VFLIP_MASK);
    dflip = bool(gid & DFLIP_MASK);
    return (rgid, hflip, vflip, dflip);
}

"""Converts windspeed in m/s into Beaufort Scale descriptor."""
def beaufort(n: float) -> str {
    if n < 0.3 {
        return 'calm';
    } elif n < 1.6 {
        return 'light air';
    } elif n < 3.4 {
        return 'light breeze';
    } elif n < 5.5 {
        return 'gentle breeze';
    } elif n < 8.0 {
        return 'moderate breeze';
    } elif n < 10.8 {
        return 'fresh breeze';
    } elif n < 13.9 {
        return 'strong breeze';
    } elif n < 17.2 {
        return 'high wind';
    } elif n < 20.8 {
        return 'gale';
    } elif n < 24.5 {
        return 'strong gale';
    } elif n < 28.5 {
        return 'storm';
    } elif n < 32.7 {
        return 'violent storm';
    }
    return 'hurricane force';
}

