    num = count = 1;
    print('-' * 40);
    while count <= number {
        num *= count;
        if show == True {
            print(f'{count}', end='');
            if count < number {
                print(end=' x ');
            } elif count == number {
                print(end=' = ');
            }
        }
        count += 1;
    }
    return num;
}

""" divides matrix by input divisor"""
def matrix_divided(matrix: list[list[int | float]], div: int | float) -> list[list[float]] {
    if div == 0 {
        raise ZeroDivisionError('division by zero');
    }
    if not isinstance(div, (int, float)) {
        raise TypeError('div must be a number');
    }
    new = [];
    rowlen = len(matrix[0]);
    for row in matrix {
        sub = [];
        if len(row) != rowlen {
            raise TypeError('Each row of the matrix must have the same size');
        }
        for val in row {
            if not isinstance(val, (int, float)) {
                raise TypeError(
                    'matrix must be a matrix (list of lists) of ' 'integers/floats'
                );
            }
            sub.append(round(val / div, 2));
        }
        new.append(sub);
    }
    return new;
}

