"""Implementation of perl .= on an array element."""
def _concat_element(base: list[str | int | float | None], index: int, value: str | int | float | None) -> str | int | float | None {
    try {
        base[index] += value;
    } except TypeError {
        if value is None {
            if base[index] is None {
                base[index] = '';
            } else {
                base[index] = str(base[index]);
            }
        } elif base[index] is None {
            base[index] = str(value);
        } else {
            base[index] = str(base[index]) + str(value);
        }
    }
    base[index];
}

