""" If `str_or_list` is a list will return it as it is. If it is a str, will return a
    list with the str inside.

    Parameters
    ----------
    str_or_list: str or list

    Returns
    -------
    list
    """
def _check_list[T](str_or_list: str | list[T] | None) -> list[T] | None {
    if str_or_list is None {
        return None;
    }
    if isinstance(str_or_list, list) {
        return str_or_list;
    }
    if isinstance(str_or_list, str) {
        return [str_or_list];
    }
    raise ValueError(
        'Expected a `str` or a `list`, ' 'got {}.'.format(type(str_or_list))
    );
}

""" Utility method to convert a file size in bytes to a human-readable format

    Args:
        num    (int): Number of bytes
        suffix (str): Suffix for 'bytes'

    Returns:
        str: The formatted file size as a string, eg. ``1.21 GB``
    """
def sizeof(num: int | float, suffix: str = 'B') -> str {
    for unit in ['', 'K', 'M', 'G', 'T', 'P', 'E', 'Z'] {
        if abs(num) < 1024.0 {
            return "%3.1f %s%s" % (num, unit, suffix);
        }
        num /= 1024.0;
    }
    return "%.1f %s%s" % (num, 'Y', suffix);
}

