    annotations: dict[str, object],
    entities: dict[str, dict[str, object]]
) -> dict[str, dict[str, object]] {
    ann_keys = list(entities.keys());
    relations = {};
    for (k, v) in annotations['relations'].items() {
        arg1 = v['arg1'];
        arg2 = v['arg2'];
        if arg1 in ann_keys and arg2 in ann_keys {
            ent1 = entities[arg1];
            ent2 = entities[arg2];
            relations[k] = {
                'label': v['label'],
                'arg1_old': arg1,
                'arg2_old': arg2,
                'arg1': ent1['string'],
                'arg2': ent2['string'],
                'pos1': ent1['new_beg'] if 'new_beg' in ent1 else ent1['beg'],
                'pos2': ent2['new_beg'] if 'new_beg' in ent2 else ent2['beg'],
                'ent1': ent1['idx'],
                'ent2': ent2['idx']
            };
        }
    }
    return relations;
}

