"""Determine if dicts a and b have the same keys."""
def same_keys(a: dict[object, object], b: dict[object, object]) -> bool {
    for ak in a {
        if ak not in b {
            return False;
        }
    }
    for bk in b {
        if bk not in a {
            return False;
        }
    }
    return True;
}

"""Cube of x."""
def cube(x: int | float) -> int | float {
    x * x * x
}

"""
The total possible combination number is Xn ... X2 * X1 = total.
"""
def getTotalCombinationNumRecursion(n: int, total: int = 0) -> int {
    if n == 1 {
        return total;
    }
    if total == 0 {
        total = n;
    }
    n -= 1;
    total *= n;
    return getTotalCombinationNumRecursion(n, total);
}

"""Generate a frequency list from a dictionary."""
def generate_freq_list(d: dict[str, int]) -> list[tuple[int, str, int, float]] {
    total = sum(d.values());
    freq_list = sorted(d.items(), key=lambda (x: tuple[str, int]) { x[1]; }, reverse=True);
    return [
        (index + 1, key, value, round((value as int) / (total as int), 2))
        for (index, (key, value)) in enumerate(freq_list)
    ];
}

"""Converts the given value to a valid numerical skill rating."""
def to_rating(value: int | float | str) -> float {
    if `type(value) not in [int, float, str] {
        raise ValueError(
            "Cannot convert %s value '%s' to a rating. Only str and numerical types are allowed."
            % (`type(value), value)
        );
    }
    try {
        rating = float(value);
    } except ValueError as e {
        raise ValueError("Failed to convert '%s' to a numerical rating" % value, e);
    }
    if rating < 0 {
        raise ValueError(
            "Invalid rating: '%s'. Ratings must be larger than or equal to zero."
            % value
        );
    }
    return rating;
}

