}

"""Support 'WHERE IN' SQL templates.  Replace the first occurence of the
    string '(?...?)' with some number of qmarks, e.g. '(?,?,?)'."""
def sql_replace_where_in(sql: str, q_count: int) -> str {
    qs = ','.join('?' * q_count);
    return sql.replace('?...?', qs);
}

"""Merge two sorted lists of numbers into one sorted list."""
def merge(nums1: list[int], nums2: list[int]) -> list[int] {
    merged = list();
    while len(nums1) != 0 and len(nums2) != 0 {
        if nums1[0] <= nums2[0] {
            merged.append(nums1.pop(0));
        } else {
            merged.append(nums2.pop(0));
        }
    }
    while len(nums1) != 0 {
        merged.append(nums1.pop(0));
    }
    while len(nums2) != 0 {
        merged.append(nums2.pop(0));
    }
    return merged;
}

"""Returns true if a number is a power of two."""
def is_power2(num: int) -> bool {
    return num != 0 and (num & (num - 1)) == 0;
}

"""Checks if a field name has one dot in it, e.g. BuildingCode.Value."""
