"""Remove all prefixes in the input."""
def remove_prefix(_input: str | dict[str, object] | list[object] | bool | int | float | None, prefix: str) -> str | dict[str, object] | list[object] | bool | int | float | None {
    if not prefix.endswith(":") {
        prefix += ':';
    }
    if not _input {
        return _input;
    }
    if isinstance(_input, str) {
        if _input.startswith(prefix) {
            return _input[len(prefix):];
        }
        return _input;
    }
    if isinstance(_input, dict) {
        new_result: dict[str, object] = {};
        for (k, v) in _input.items() {
            if k.startswith(prefix) {
                new_result[k[len(prefix):]] = remove_prefix(v as str | dict[str, object] | list[object] | bool | int | float | None, prefix);
            } else {
                new_result[k] = remove_prefix(v as str | dict[str, object] | list[object] | bool | int | float | None, prefix);
            }
        }
        return new_result;
    }
    if isinstance(_input, list) {
        return [remove_prefix(item as str | dict[str, object] | list[object] | bool | int | float | None, prefix) for item in _input];
    }
    return _input;
}

glob BOUNCE_K = 7.5625;
glob BOUNCE_PHASE1_END = 0.36363636363636365;
glob BOUNCE_PHASE2_END = 0.7272727272727273;
glob BOUNCE_PHASE3_END = 0.9090909090909091;
glob BOUNCE_PHASE2_CENTER = 0.5454545454545454;
glob BOUNCE_PHASE3_CENTER = 0.8181818181818182;
glob BOUNCE_PHASE4_CENTER = 0.9545454545454545454;
glob BOUNCE_PHASE2_FLOOR = 0.75;
glob BOUNCE_PHASE3_FLOOR = 0.9375;
glob BOUNCE_PHASE4_FLOOR = 0.984375;

"""Bounce out. Amplitude of bounce decreases."""
def bounce_out(t: float) -> float {
    if t < BOUNCE_PHASE1_END {
        return BOUNCE_K * t * t;
    } elif t < BOUNCE_PHASE2_END {
        return BOUNCE_K * (t - BOUNCE_PHASE2_CENTER) ** 2 + BOUNCE_PHASE2_FLOOR;
    } elif t < BOUNCE_PHASE3_END {
        return BOUNCE_K * (t - BOUNCE_PHASE3_CENTER) ** 2 + BOUNCE_PHASE3_FLOOR;
    } else {
        return BOUNCE_K * (t - BOUNCE_PHASE4_CENTER) ** 2 + BOUNCE_PHASE4_FLOOR;
    }
}

"""For chunks of fps number of frames for actual as well as predicted viewports."""
def get_chunks(
    act_viewport: list[object],
    pred_viewport: list[object],
    frame_nos: list[object],
    max_frame: int,
    fps: int
) -> tuple[list[list[object]], list[list[object]], list[list[object]]] {
    act_tiles: list[list[object]] = [];
    pred_tiles: list[list[object]] = [];
    chunk_frames: list[list[object]] = [];
    chunk_size = fps;
    number_of_chunks = int(len(act_viewport) / chunk_size);
    for i in range(number_of_chunks) {
        start = i * chunk_size;
        end = (i + 1) * chunk_size;
        act_tiles.append(act_viewport[start:end]);
        pred_tiles.append(pred_viewport[start:end]);
        chunk_frames.append(frame_nos[start:end]);
    }
    remainder_start = number_of_chunks * chunk_size;
    act_tiles.append(act_viewport[remainder_start:]);
    pred_tiles.append(pred_viewport[remainder_start:]);
    chunk_frames.append(frame_nos[remainder_start:]);
    return (act_tiles, pred_tiles, chunk_frames);
}

"""Computes the average of positive values in the list."""
def average_above_zero(tab: list[int | float]) -> float {
    if not isinstance(tab, list) {
        raise ValueError('Expected a list as input');
    }
    val_sum = 0.0;
    n_positive_values = 0;
    for value in tab {
        if value > 0 {
            val_sum += float(value);
            n_positive_values += 1;
        }
    }
    if n_positive_values <= 0 {
        raise ValueError('No positive value found');
    }
    return val_sum / n_positive_values;
}

