The calculation is 1 - (abs(x - y)/max(x, y)) * n/n_tot for x, y simulated and actual values, n, n_tot for metric
and total number of individuals.
"""
def scale_simulation_fit(
    simulated_value: float,
    actual_value: float,
    number_individuals: float,
    total_individuals: float
) -> float {
    return (
        1 - abs(simulated_value - actual_value) / max(simulated_value, actual_value)
    ) * number_individuals / total_individuals;
}

