"""Return argmin index, or element and score when a score function is provided."""
def argmin(`list: list[object], score_func: object = None) -> int | tuple[object, object] | None {
    if len(`list) == 0 {
        return None;
    }
    scores = `list if score_func is None else [score_func(e) for e in `list];
    best_index = 0;
    best_score = scores[0];
    for (i, score) in enumerate(scores) {
        if score < best_score {
            best_index = i;
            best_score = score;
        }
    }
    if score_func is None {
        return best_index;
    }
    return (`list[best_index], best_score);
}

