"""
Method to obtain module and class_name from a module path.

Returns tuple containing class_name and module.
"""
def process_path(module_path: str) -> tuple[str, str] {
    if module_path == 'numpy.ndarray' {
        return ('StorageNumpy', 'hecuba.hnumpy');
    }
    if module_path == 'StorageDict' {
        return ('StorageDict', 'hecuba.hdict');
    }
    last = 0;
    for (idx, ch) in enumerate(module_path) {
        if ch == '.' and idx > last {
            last = idx;
        }
    }
    module = module_path[:last];
    class_name = module_path[(last + 1):];
    return (class_name, module);
}

"""Returns the subarray having the greatest product and the greatest product."""
def greatest_product_subarray(arr: list[int], subarray_len: int) -> list[int] | tuple[list[int], int] {
    if subarray_len >= len(arr) {
        return arr;
    }
    prod = 1;
    for i in range(subarray_len) {
        prod *= arr[i];
    }
    max_prod = prod;
    end_index = subarray_len - 1;
    i = end_index + 1;
    while i in range(end_index + 1, len(arr)) {
        if arr[i] != 0 {
            if arr[i - subarray_len] == 0 {
                prod = 1;
                for j in range(i - subarray_len + 1, i + 1) {
                    prod *= arr[j];
                }
            } else {
                prod = (prod // arr[i - subarray_len]) * arr[i];
            }
            if prod > max_prod {
                max_prod = prod;
                end_index = i;
            }
            i += 1;
        } else {
            i = i + subarray_len;
        }
    }
    return (arr[(end_index - subarray_len + 1):(end_index + 1)], max_prod);
}

