"""Divide a by b and round result to the nearest integer."""
def _divide_and_round(a: int, b: int) -> int {
    (q, r) = divmod(a, b);
    r *= 2;
    greater_than_half = r > b if b > 0 else r < b;
    if greater_than_half or r == b and q % 2 == 1 {
        q += 1;
    }
    return q;
}

