"""Symmetrically extend the range given by the `min_max` pair.
   The new range will be 1 + `extend_ratio` larger than the original range.
"""
def extend_range(min_max: tuple[float, float], extend_ratio: float = 0.2) -> tuple[float, float] {
    mme = (min_max[1] - min_max[0]) * extend_ratio / 2;
    return (min_max[0] - mme, min_max[1] + mme);
}

"""
Given a grid of points xi (sorted smallest to largest) find in
which interval the point x sits.  Returns i, where x \in [ xi[i],xi[i+1] ].
Raise ValueError if x is not inside the grid.
"""
def interval_idx(x: float, xi: list[float]) -> int {
    assert x >= xi[0] and x <= xi[-1], ValueError(
        'x=%g not in [%g,%g]' % (x, xi[0], xi[-1])
    );
    for i in range(len(xi) - 1) {
        if xi[i] <= x and x <= xi[i + 1] {
            return i;
        }
    }
}

