"""Return substring from a text based on start and end substrings delimited by ::."""
def get_fragment(text: str, startend: str) -> str | None {
    parts = startend.split("::");
    if parts[0] not in text or parts[1] not in text {
        return;
    }
    start_idx = text.index(parts[0]);
    end_idx = text.index(parts[1]);
    if end_idx < start_idx {
        return;
    }
    return text[start_idx:end_idx + len(parts[1])];
}

