"""Returns a list of points which lie in a line defined by two endpoints"""
def get_lattice_points(tup1: tuple[int, int], tup2: tuple[int, int], check_diagonals: bool = True) -> list[tuple[int, int]] {
    (x1, y1) = (tup1[0], tup1[1]);
    (x2, y2) = (tup2[0], tup2[1]);
    if y1 == y2 {
        if x1 <= x2 {
            return [(i, y1) for i in range(x1, x2 + 1)];
        }
        return [(i, y1) for i in range(x2, x1 + 1)];
    } elif x1 == x2 {
        if y1 <= y2 {
            return [(x1, i) for i in range(y1, y2 + 1)];
        }
        return [(x1, i) for i in range(y2, y1 + 1)];
    } elif check_diagonals {
        slope = (y2 - y1) / (x2 - x1);
        y_int = y1 - (slope * x1);
        if x1 <= x2 {
            return [
                (i, int(slope * i + y_int))
                for i in range(x1, x2 + 1)
                if (slope * i + y_int).is_integer()
            ];
        }
        return [
            (i, int(slope * i + y_int))
            for i in range(x2, x1 + 1)
            if (slope * i + y_int).is_integer()
        ];
    }
}

"""
    What is the minimum number of trials we need to drop eggs to determine which floors of a building are safe for
    dropping eggs, given n eggs and k floors?
    :param n: number of eggs
    :param k: number of floors
    :return: the minimum number of trials

    >>> egg_drop(1, 5)
    5
    >>> egg_drop(2,36)
    8
    """
def egg_drop(n: int, k: int) -> int {
    if n == 1 {
        return k;
    }
    if k == 1 or k == 0 {
        return k;
    }
    return 1 + min([
        max(egg_drop(n - 1, x - 1), egg_drop(n, k - x))
        for x in range(1, k + 1)
    ]);
}

