    Gi1/0/1 becomes ('Gi', '1/0/1') or GigabitEthernet1/0/1 becomes ('GigabitEthernet', '1/0/1')"""
def parse_input(input: str) -> tuple[str, str] {
    interface_name = '';
    interface_number = '';
    x = 0;
    for letter in input {
        if letter.isdigit() {
            interface_number = input[x:];
            break;
        } else {
            interface_name += letter;
        }
        x += 1;
    }
    return (interface_name.strip(' '), interface_number.strip(' '));
}

"""
    Ignore empty lines, comments and editable requirements

    :param list entries: List of entries

    :returns: mapping from a project to its version specifier
    :rtype: dict
    """
def process_entries(entries: list[str]) -> dict[str, str] {
    data = {};
    for e in entries {
        e = e.strip();
        if e and not e.startswith('#') and not e.startswith('-e') {
            for comparison in ('==', '<=') {
                parts = e.split(comparison);
                if len(parts) == 2 {
                    project_name = parts[0];
                    version = parts[1];
                    data[project_name] = comparison + version;
                    break;
                }
            } else {
                raise ValueError("Unexpected syntax '{0}'".format(e));
            }
        }
    }
    return data;
}

"""
    Similar to keras.preprocessing.sequence.pad_sequence but using Sample as higher level
    abstraction.
    pad_func is a pad class generator.
    """
def pad_sequences(
    sequences: list[Sequence], pad_func: Callable[[], int], maxlen: int | None = None
) -> list[list[int]] {
    ret = [];
    max_value = max(map(len, sequences));
    if maxlen is None {
        maxlen = max_value;
    }
    for sequence in sequences {
        cur_seq = list(sequence[:maxlen]);
        cur_seq.extend([pad_func()] * (maxlen - len(sequence)));
        ret.append(cur_seq);
    }
    return ret;
}

