"""Binary search on a sorted array.

    Arguments:
    key - filter for objects in the array
    start - 0-indexed starting marker on the array to search
    end - exclusive ending marker on the array to search
    """
def binary_search(
    array: list[int] | None,
    query: int,
    key: Callable[[int], int] = lambda (a: int) { a; },
    start: int = 0,
    end: int = -1
) -> int | None {
    if array is None or len(array) == 0 {
        return None;
    }
    if end == -1 {
        end = len(array);
    } elif start >= end {
        return None;
    }
    mid = int(start + (end - start) / 2);
    compare_to = key(array[mid]);
    if query < compare_to {
        return binary_search(array, query, key, start, mid);
    } elif query > compare_to {
        return binary_search(array, query, key, mid + 1, end);
    } else {
        return array[mid];
    }
}

"""Returns velocities from a perfectly elastic collision between masses m1 and m2."""
def Elastic(m1: float, m2: float, v1: float, v2: float) -> tuple[float, float] {
    vp2 = (m2 * v2 + m1 * (2.0 * v1 - v2)) / (m1 + m2);
    vp1 = vp2 + v2 - v1;
    return (vp1, vp2);
}

"""Approximation for the expected value of Z_{right}^eF (right elegible first)."""
def func_right_elegible_first(
    k_idx: int,
    k_right: float,
    s_right: float,
    cap_right_closed: int,
    closed_ZG_right: float
) -> float {
    mu = k_idx + 1;
    lamb = mu / 2;
    k_0 = k_right;
    s_0 = s_right;
    kp = cap_right_closed;
    closed_EF_right = (
        k_0 * (kp - (2 * s_0) - 1) * (1 - (1 - k_0 / kp) ** (lamb - s_0))
    ) / 4;
    closed_EF_right = closed_EF_right - (
        kp
        * (1 - k_0 / kp)
        * (
            1
            - (1 + (kp - s_0 - 1) * k_0 / kp)
            * (1 - k_0 / kp) ** ((lamb - s_0) + 1)
        )
    ) / (4 * k_0);
    closed_EF_right = closed_EF_right + closed_ZG_right;
    return closed_EF_right;
}

