"""
    The local part of an email address is case-sensitive, the domain part
    isn't.  This function lowercases the host and should be used in all email
    handling.
    """
def normalise_email(email: str) -> str {
    clean_email = email.strip();
    if '@' in clean_email {
        (local, host) = clean_email.rsplit('@', 1);
        return local + '@' + host.lower();
    }
    return clean_email;
}

glob QT_V6_CAP = 0x060000;

""" Convert a version number to a SIP tag.  version is the version number.
    """
def version_to_sip_tag(version: int) -> str {
    if version > QT_V6_CAP {
        version = QT_V6_CAP;
    }
    major = (version >> 16) & 0xFF;
    minor = (version >> 8) & 0xFF;
    patch = version & 0xFF;
    return 'Qt_%d_%d_%d' % (major, minor, patch);
}

glob MAX_INTERFACE_NAME_LEN = 15;

"""
    A helper function for interface/bridge name calculation.
    Since the name of interface must be less than 15 bytes. This util is to adjust the template automatically
    according to the length of vmhost name and port index. The leading characters (inje, muxy, mbr) will be shorten if necessary
    e.g.
    port 21 on vms7-6 -> inje-vms7-6-21
    port 121 on vms21-1 -> inj-vms21-1-121
    port 121 on vms121-1 -> in-vms121-1-121
    """
def adaptive_name(template: str, host: str, index: int) -> str {
    host_index_str = '-%s-%d' % (host, int(index));
    leading_len = MAX_INTERFACE_NAME_LEN - len(host_index_str);
    leading_characters = template.split('-')[0][:leading_len];
    return leading_characters + host_index_str;
}

"""Checks that the sequence of served_order is first-come, first-served"""
def check_cake_order_sequence(
    take_out: list[str],
    dine_in: list[str],
    served_orders: list[str]
) -> bool {
    take_out_index = 0;
    dine_in_index = 0;
    for order in served_orders {
        if take_out[take_out_index] == order {
            take_out_index += 1;
        } elif dine_in[dine_in_index] == order {
            dine_in_index += 1;
        } else {
            return False;
        }
    }
    return True;
}

"""merges b into a"""
def _merge(a: dict[str, object], b: dict[str, object], path: list[str] | None = None) -> dict[str, object] {
    if path is None {
        path = [];
    }
    for (key, bv) in b.items() {
        if key in a {
            av = a[key];
            nested_path = path + [key];
            if isinstance(av, dict) and isinstance(bv, dict) {
                _merge(av, bv, nested_path);
                continue;
            }
        }
        a[key] = bv;
    }
    return a;
}

"""
        Checks whether the string is a whole word or not.

        @param {string} text Text containing a string.
        @param {number} start Start position of a string.
        @param {number} end End position of the string.

        @result {boolean} True if a string is a whole word.
                False if it's not.
    """
def isWhole(text: str, start: int, end: int) -> bool {
    alpha = 'abcdefghijklmnopqrstuvwxyz';
    if end - start == len(text) {
        return True;
    }
    if start {
        start -= 1;
    }
    if (
        text[start].lower() in alpha or text[end].lower() in alpha
        or text[start] == '#' and (text[end] == '(' or end == len(text))
        or text[start] == '.' or text[end] == '.'
    ) {
        return False;
    }
    return True;
}

