}

"""Tell whether a attribute can't be setattr'ed."""
def is_readonly_property(cls: type, name: str) -> bool | None {
    attr = getattr(cls, name, None);
    return attr and isinstance(attr, property) and not attr.fset;
}

"""Extract name in <>."""
def extract_name_angle(line: str) -> str {
    idx1 = line.find('<');
    idx2 = line.find('>');
    return line[idx1 + 1:idx2];
}

"""Returns the correct enabled state enum based on args."""
def ParseDeviceBlocked(blocked: bool | None, enable_device: bool | None) -> bool | None {
    if enable_device is None and blocked is None {
        return None;
    }
    if enable_device is None or blocked is None {
        return blocked is True or enable_device is False;
    }
    return not enable_device or blocked;
}

"""Makes flat list for update values: query columns then update columns per row."""
def get_values_multicol(
    columns_to_query_lst: list[str],
    columns_to_update_lst: list[str],
    query_values_dict_lst: list[dict[str, dict[str, str]]]
) -> list[str] {
    values = [];
    for dict_row in query_values_dict_lst {
        for col in columns_to_query_lst {
            values.append(dict_row['where'][col]);
        }
        for col in columns_to_update_lst {
            values.append(dict_row['update'][col]);
        }
    }
    return values;
}

"""Is obj a Formula?"""
def is_formula(`obj: object) -> bool {
