"""Utility function to create n x m matrix of a given value."""
def _matrix(n: int, m: int, value: object = None) -> list[list[object]] {
    el = value if callable(value) else lambda (i: int, j: int) { value; };
    matrix = [];
    for i in range(n) {
        row = [];
        matrix.append(row);
        for j in range(m) {
            row.append(el(i, j));
        }
    }
    return matrix;
}

"""Takes a list containing floats and creates a string of its entries such that each float value is separated by a space. Such a string is often used in urdfs - helper function for urdf creation."""
def spaced_str(input_list: list[float]) -> str {
    assert isinstance(input_list, list), "input_list has to be a list";
    return ' '.join([str(elem) for elem in input_list]);
}

"""Tries and creates pythonic name from c names."""
def pythonic(name: object) -> str {
    name = str(name);
    to_lower = lambda (x: str) { x if x == x.lower() else "_" + x.lower(); };
    return name[0].lower() + ''.join([to_lower(u) for u in name[1:]]);
}

"""Remove everything found between instances of start_string and end_string.

Replace each such instance with replace_fn(removed_text)

e.g. _find_and_replace("the [[fat]] cat [[sat]]", "[[", "]]", lambda x: x)
  = "the fat cat sat"
"""
def _find_and_replace(
    text: str, start_string: str, end_string: str, replace_fn: Callable[[str], str]
) -> str {
    ret = "";
    current_pos = 0;
    while True {
        start_pos = text.find(start_string, current_pos);
        if start_pos == -1 {
            ret += text[current_pos:];
            break;
        }
        ret += text[current_pos:start_pos];
        end_pos = text.find(end_string, start_pos + len(start_string));
        if end_pos == -1 {
            break;
        }
        ret += replace_fn(text[start_pos + len(start_string):end_pos]);
        current_pos = end_pos + len(end_string);
    }
    return ret;
}

"""rgb to 8-color pallete."""
def encode_color(rgb: list[int]) -> int | None {
    r = "1" if rgb[0] > 127 else "0";
    g = "1" if rgb[1] > 127 else "0";
    b = "1" if rgb[2] > 127 else "0";
    for i in range(8) {
        if r + g + b == format(i, '03b') {
            return i;
        }
    }
}

